class Solution {
    public int digits(int n) {
        int product = 1;
        boolean hasOdd = false;

        while(n != 0){
            int digit = n % 10;
            if(digit % 2 != 0){
                hasOdd = true;
                product *= digit;
            }
            n = n / 10;
        }
        if(!hasOdd){
            return 0;
        }

        return product;
    }
